// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count all Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th from 0001-01-01 ---
var date = new DateTime(1, 1, 13); // start on the 13th of January, year 1
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// --- Count Friday the 13ths in a full 400-year cycle (years 1–400) ---
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// --- Bonus: breakdown by month ---
Console.WriteLine("\nBreakdown by month:");
for (int month = 1; month <= 12; month++)
{
    int monthCount = 0;
    for (int year = 1; year <= 400; year++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            monthCount++;
    }
    Console.WriteLine($"  {new DateTime(2000, month, 1):MMMM,-12} {monthCount}");
}

